}
recursive fn callerDependent(source: const blot_check_core::Types&,ty: u32,depth: i64) -> bool {
 if ty==0||depth>=256 { return false; } let n=source.node(ty); let tag=n.tag;
 if tag==blot_check_types::Tag.function||tag==blot_check_types::Tag.provider { for label in source.rowLabels(n.c) { for argument in source.operationArguments(label) { if callerDependent(source,argument,depth+1) { return true; } } } }
 if tag==blot_check_types::Tag.variable||tag==blot_check_types::Tag.bound { return true; }
 if tag==blot_check_types::Tag.usage||tag==blot_check_types::Tag.forall { return callerDependent(source,n.a,depth+1); }
 if tag==blot_check_types::Tag.function||tag==blot_check_types::Tag.provider { return callerDependent(source,n.a,depth+1)||callerDependent(source,n.b,depth+1); }
 if tag==blot_check_types::Tag.array||tag==blot_check_types::Tag.list||tag==blot_check_types::Tag.cursor||tag==blot_check_types::Tag.resolver { return callerDependent(source,n.a,depth+1); }
 if tag==blot_check_types::Tag.state_provider { return callerDependent(source,n.a,depth+1)||callerDependent(source,n.b,depth+1)||callerDependent(source,n.c,depth+1); }
 if tag==blot_check_types::Tag.product { for child in source.list(blot_check_types::List {n.a,n.b}) { if callerDependent(source,child,depth+1) { return true; } } }
 else if tag==blot_check_types::Tag.record { for index in 0..n.b { if callerDependent(source,source.recordField(n,index).ty,depth+1) { return true; } } }
 else if tag==blot_check_types::Tag.nominal { for child in source.nominalArguments(n) { if callerDependent(source,child,depth+1) { return true; } } } return false;
}
fn callerDependentUse(module: const Module&,id: u32) -> bool {
 let n=module.node(id); if n.tag==blot_check_core::Tag.call { for arg in module.children(id) { if callerDependent(module.types,module.typeOf(arg),0) { return true; } } }
 else if n.tag==blot_check_core::Tag.apply { return callerDependent(module.types,module.typeOf(n.b),0); }
 else if n.tag==blot_check_core::Tag.associated||n.tag==blot_check_core::Tag.scalar { return callerDependent(module.types,module.typeOf(n.a),0)||callerDependent(module.types,module.typeOf(n.b),0); }
 else if n.tag==blot_check_core::Tag.project { return callerDependent(module.types,module.typeOf(n.a),0); } else if n.tag==blot_check_core::Tag.result_associated { return callerDependent(module.types,n.ty,0); } return false;
}
fn obligationDependent(source: const blot_check_core::Types&,obligation: blot_check_core::Obligation) -> bool {
 if obligation.kind==blot_check_types::ObligationKind.dispatch { return callerDependent(source,obligation.ty,0)||callerDependent(source,obligation.other,0); }
 if obligation.kind==blot_check_types::ObligationKind.result_dispatch { return callerDependent(source,obligation.result,0); }
 return callerDependent(source,obligation.ty,0)||callerDependent(source,obligation.other,0)||callerDependent(source,obligation.result,0);
}
